1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root {
9	    --cell: 28px;
10	    --bg: #14161c;
11	    --panel: #1d2029;
12	    --grid: #262a35;
13	    --text: #e8eaf0;
14	    --muted: #8a90a0;
15	  }
16	  * { box-sizing: border-box; }
17	  body {
18	    margin: 0;
19	    min-height: 100vh;
20	    display: flex;
21	    align-items: center;
22	    justify-content: center;
23	    background: var(--bg);
24	    color: var(--text);
25	    font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
26	  }
27	  .game {
28	    display: flex;
29	    gap: 20px;
30	    align-items: flex-start;
31	    padding: 16px;
32	  }
33	  .board {
34	    display: grid;
35	    grid-template-columns: repeat(10, var(--cell));
36	    grid-template-rows: repeat(20, var(--cell));
37	    gap: 1px;
38	    padding: 1px;
39	    background: var(--grid);
40	    border: 2px solid #3a3f4d;
41	    border-radius: 4px;
42	    position: relative;
43	  }
44	  .cell { background: var(--bg); }
45	  .side {
46	    display: flex;
47	    flex-direction: column;
48	    gap: 12px;
49	    min-width: 140px;
50	  }
51	  .box {
52	    background: var(--panel);
53	    border-radius: 6px;
54	    padding: 10px 12px;
55	  }
56	  .label {
57	    font-size: 11px;
58	    text-transform: uppercase;
59	    letter-spacing: 0.08em;
60	    color: var(--muted);
61	  }
62	  .value { font-size: 22px; font-weight: 600; font-variant-numeric: tabular-nums; }
63	  .preview {
64	    display: grid;
65	    grid-template-columns: repeat(4, 18px);
66	    grid-template-rows: repeat(2, 18px);
67	    gap: 1px;
68	    margin-top: 8px;
69	  }
70	  .preview .mini { background: transparent; }
71	  .help { color: var(--muted); font-size: 12px; }
72	  .help kbd {
73	    background: #2b2f3a;
74	    border-radius: 3px;
75	    padding: 0 4px;
76	    font: inherit;
77	    color: var(--text);
78	  }
79	  .overlay {
80	    position: absolute;
81	    inset: 0;
82	    display: flex;
83	    flex-direction: column;
84	    align-items: center;
85	    justify-content: center;
86	    gap: 10px;
87	    background: rgba(10, 11, 15, 0.78);
88	    font-size: 20px;
89	    font-weight: 600;
90	  }
91	  .overlay button {
92	    font: inherit;
93	    font-size: 14px;
94	    padding: 6px 14px;
95	    border: 0;
96	    border-radius: 4px;
97	    background: #4a8cff;
98	    color: #fff;
99	    cursor: pointer;
100	  }
101	  .overlay[hidden] { display: none; }
102	
103	  /* Piece colours */
104	  .p-I { background: #30c7e6; }
105	  .p-O { background: #f2d33a; }
106	  .p-T { background: #a35ee0; }
107	  .p-S { background: #4ccf5a; }
108	  .p-Z { background: #e8474a; }
109	  .p-J { background: #3b6ee8; }
110	  .p-L { background: #f09a2e; }
111	</style>
112	</head>
113	<body>
114	<div class="game">
115	  <div class="board" data-testid="board" id="board">
116	    <div class="overlay" id="overlay" hidden>
117	      <div>Game over</div>
118	      <button type="button" id="restart">Play again</button>
119	    </div>
120	  </div>
121	  <div class="side">
122	    <div class="box">
123	      <div class="label">Score</div>
124	      <div class="value" data-testid="score" id="score">0</div>
125	    </div>
126	    <div class="box">
127	      <div class="label">Level</div>
128	      <div class="value" data-testid="level" id="level">1</div>
129	    </div>
130	    <div class="box">
131	      <div class="label">Lines</div>
132	      <div class="value" data-testid="lines" id="lines">0</div>
133	    </div>
134	    <div class="box">
135	      <div class="label">Next</div>
136	      <div class="preview" id="preview"></div>
137	    </div>
138	    <div class="box help">
139	      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
140	      <div><kbd>↓</kbd> Soft drop</div>
141	      <div><kbd>Space</kbd> Hard drop</div>
142	    </div>
143	  </div>
144	</div>
145	
146	<script>
147	(function () {
148	  "use strict";
149	
150	  var ROWS = 20;
151	  var COLS = 10;
152	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
153	
154	  // Spawn shapes as [row, col] offsets. Top row of every shape is row 0.
155	  var SHAPES = {
156	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
157	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
158	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
159	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
160	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
161	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
162	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
163	  };
164	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
165	
166	  // ---- State ----
167	  var board;       // ROWS x COLS array of piece letters or null
168	  var current;     // { type, row, col, shape } or null
169	  var queue;       // upcoming piece letters, soonest first
170	  var bag;         // 7-bag for the random generator
171	  var score, level, lines, status;
172	  var timer = null;
173	
174	  function emptyBoard() {
175	    var b = [];
176	    for (var r = 0; r < ROWS; r++) {
177	      var row = [];
178	      for (var c = 0; c < COLS; c++) row.push(null);
179	      b.push(row);
180	    }
181	    return b;
182	  }
183	
184	  function randomPiece() {
185	    if (!bag || bag.length === 0) {
186	      bag = TYPES.slice();
187	      for (var i = bag.length - 1; i > 0; i--) {
188	        var j = Math.floor(Math.random() * (i + 1));
189	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
190	      }
191	    }
192	    return bag.pop();
193	  }
194	
195	  function sanitizeQueue(q) {
196	    if (!Array.isArray(q)) return [];
197	    return q.map(function (x) { return String(x).toUpperCase(); })
198	            .filter(function (x) { return TYPES.indexOf(x) !== -1; });
199	  }
200	
201	  // Keep at least one upcoming piece so there is always something to preview.
202	  function fillQueue() {
203	    while (queue.length < 1) queue.push(randomPiece());
204	  }
205	
206	  function pieceCells(p, dRow, dCol) {
207	    var out = [];
208	    for (var i = 0; i < p.shape.length; i++) {
209	      out.push([p.row + p.shape[i][0] + (dRow || 0), p.col + p.shape[i][1] + (dCol || 0)]);
210	    }
211	    return out;
212	  }
213	
214	  function fits(p, dRow, dCol) {
215	    var cells = pieceCells(p, dRow, dCol);
216	    for (var i = 0; i < cells.length; i++) {
217	      var r = cells[i][0], c = cells[i][1];
218	      if (c < 0 || c >= COLS || r >= ROWS) return false;
219	      if (r >= 0 && board[r][c]) return false;
220	    }
221	    return true;
222	  }
223	
224	  function spawn() {
225	    fillQueue();
226	    var type = queue.shift();
227	    fillQueue();
228	    var p = { type: type, row: 0, col: SPAWN_COL[type], shape: SHAPES[type] };
229	    if (!fits(p, 0, 0)) {
230	      current = null;
231	      status = "over";
232	      stopTimer();
233	      return;
234	    }
235	    current = p;
236	  }
237	
238	  function lock() {
239	    var cells = pieceCells(current, 0, 0);
240	    for (var i = 0; i < cells.length; i++) {
241	      var r = cells[i][0], c = cells[i][1];
242	      if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = current.type;
243	    }
244	    current = null;
245	    spawn();
246	  }
247	
248	  // One gravity step. The real timer, tick() and soft drop all run this.
249	  function gravityStep() {
250	    if (status !== "running" || !current) return;
251	    if (fits(current, 1, 0)) {
252	      current.row += 1;
253	    } else {
254	      lock();
255	    }
256	  }
257	
258	  function move(dCol) {
259	    if (status !== "running" || !current) return;
260	    if (fits(current, 0, dCol)) current.col += dCol;
261	  }
262	
263	  function hardDrop() {
264	    if (status !== "running" || !current) return;
265	    while (fits(current, 1, 0)) current.row += 1;
266	    lock();
267	  }
268	
269	  var ACTIONS = {
270	    left: function () { move(-1); },
271	    right: function () { move(1); },
272	    softDrop: gravityStep,
273	    hardDrop: hardDrop
274	  };
275	
276	  // ---- Timer ----
277	  function gravityInterval() {
278	    return Math.max(100, 1000 - (level - 1) * 100);
279	  }
280	
281	  function onTimer() {
282	    gravityStep();
283	    render();
284	  }
285	
286	  function startTimer() {
287	    stopTimer();
288	    timer = setInterval(onTimer, gravityInterval());
289	  }
290	
291	  function stopTimer() {
292	    if (timer !== null) {
293	      clearInterval(timer);
294	      timer = null;
295	    }
296	  }
297	
298	  // ---- Rendering (synchronous) ----
299	  var boardEl = document.getElementById("board");
300	  var overlayEl = document.getElementById("overlay");
301	  var scoreEl = document.getElementById("score");
302	  var levelEl = document.getElementById("level");
303	  var linesEl = document.getElementById("lines");
304	  var previewEl = document.getElementById("preview");
305	  var cellEls = [];
306	  var previewEls = [];
307	
308	  (function buildDom() {
309	    for (var r = 0; r < ROWS; r++) {
310	      var row = [];
311	      for (var c = 0; c < COLS; c++) {
312	        var el = document.createElement("div");
313	        el.className = "cell";
314	        el.setAttribute("data-testid", "cell");
315	        el.setAttribute("data-row", String(r));
316	        el.setAttribute("data-col", String(c));
317	        el.setAttribute("data-filled", "false");
318	        el.setAttribute("data-piece", "");
319	        boardEl.insertBefore(el, overlayEl);
320	        row.push(el);
321	      }
322	      cellEls.push(row);
323	    }
324	    for (var i = 0; i < 8; i++) {
325	      var m = document.createElement("div");
326	      m.className = "mini";
327	      previewEl.appendChild(m);
328	      previewEls.push(m);
329	    }
330	  })();
331	
332	  function setCell(el, type) {
333	    var piece = type || "";
334	    if (el.getAttribute("data-piece") === piece) return;
335	    el.className = piece ? "cell p-" + piece : "cell";
336	    el.setAttribute("data-filled", piece ? "true" : "false");
337	    el.setAttribute("data-piece", piece);
338	  }
339	
340	  function render() {
341	    var view = board.map(function (row) { return row.slice(); });
342	    if (current) {
343	      var cells = pieceCells(current, 0, 0);
344	      for (var i = 0; i < cells.length; i++) {
345	        var r = cells[i][0], c = cells[i][1];
346	        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) view[r][c] = current.type;
347	      }
348	    }
349	    for (var rr = 0; rr < ROWS; rr++) {
350	      for (var cc = 0; cc < COLS; cc++) setCell(cellEls[rr][cc], view[rr][cc]);
351	    }
352	
353	    scoreEl.textContent = String(score);
354	    levelEl.textContent = String(level);
355	    linesEl.textContent = String(lines);
356	
357	    for (var k = 0; k < previewEls.length; k++) previewEls[k].className = "mini";
358	    var nextType = queue[0];
359	    if (nextType) {
360	      SHAPES[nextType].forEach(function (off) {
361	        previewEls[off[0] * 4 + off[1]].className = "mini p-" + nextType;
362	      });
363	    }
364	
365	    overlayEl.hidden = status !== "over";
366	  }
367	
368	  // ---- Game control ----
369	  function newGame(q) {
370	    board = emptyBoard();
371	    bag = [];
372	    queue = sanitizeQueue(q);
373	    score = 0;
374	    level = 1;
375	    lines = 0;
376	    status = "running";
377	    current = null;
378	    spawn();
379	    if (status === "running") startTimer();
380	    render();
381	  }
382	
383	  function parseRows(rows) {
384	    var b = emptyBoard();
385	    if (!Array.isArray(rows)) return b;
386	    for (var r = 0; r < ROWS && r < rows.length; r++) {
387	      var line = String(rows[r]);
388	      for (var c = 0; c < COLS && c < line.length; c++) {
389	        var ch = line.charAt(c).toUpperCase();
390	        b[r][c] = TYPES.indexOf(ch) !== -1 ? ch : null;
391	      }
392	    }
393	    return b;
394	  }
395	
396	  function boardToRows() {
397	    return board.map(function (row) {
398	      return row.map(function (v) { return v || "."; }).join("");
399	    });
400	  }
401	
402	  // ---- Keyboard ----
403	  var KEYS = {
404	    ArrowLeft: "left",
405	    ArrowRight: "right",
406	    ArrowDown: "softDrop",
407	    " ": "hardDrop",
408	    Spacebar: "hardDrop"
409	  };
410	
411	  document.addEventListener("keydown", function (e) {
412	    if (status === "over" && e.key === "Enter") {
413	      e.preventDefault();
414	      newGame();
415	      return;
416	    }
417	    var action = KEYS[e.key];
418	    if (!action) return;
419	    e.preventDefault();
420	    ACTIONS[action]();
421	    render();
422	  });
423	
424	  document.getElementById("restart").addEventListener("click", function () {
425	    newGame();
426	  });
427	
428	  // ---- Test control surface ----
429	  window.__tetris = {
430	    newGame: function (q) { newGame(q); },
431	    setQueue: function (q) {
432	      queue = sanitizeQueue(q);
433	      fillQueue();
434	      render();
435	    },
436	    setBoard: function (rows) {
437	      board = parseRows(rows);
438	      render();
439	    },
440	    tick: function (n) {
441	      var count = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
442	      for (var i = 0; i < count; i++) gravityStep();
443	      render();
444	    },
445	    input: function (action) {
446	      var fn = ACTIONS[action];
447	      if (!fn) return;
448	      fn();
449	      render();
450	    },
451	    getBoard: function () { return boardToRows(); },
452	    getState: function () {
453	      return {
454	        current: current ? { type: current.type, cells: pieceCells(current, 0, 0) } : null,
455	        next: queue.slice(),
456	        score: score,
457	        level: level,
458	        lines: lines,
459	        status: status
460	      };
461	    }
462	  };
463	
464	  newGame();
465	})();
466	</script>
467	</body>
468	</html>
