p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep('''      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>''','''      <div><kbd>←</kbd> <kbd>→</kbd> Move</div>
      <div><kbd>↑</kbd> <kbd>X</kbd> Rotate</div>''')
rep('''  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
''','''  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };

  // The I piece has its own rotation states so it turns in place like the
  // guideline piece, without ever reaching above the piece's own row.
  var I_STATES = [
    [[0, 0], [0, 1], [0, 2], [0, 3]],
    [[0, 2], [1, 2], [2, 2], [3, 2]],
    [[1, 0], [1, 1], [1, 2], [1, 3]],
    [[0, 1], [1, 1], [2, 1], [3, 1]]
  ];
  // Sideways shifts tried, in order, when a rotated shape does not fit.
  var KICKS = [0, -1, 1, -2, 2];

  // Locking rule.
  var LOCK_DELAY = 2;      // gravity ticks a piece may spend unable to fall
  var MAX_LOCK_RESETS = 3; // times a piece may restart its lock delay
''')
rep('''  var current;     // { type, row, col, shape } or null''',
    '''  var current;     // { type, row, col, rot, shape, lockTicks, lockResets } or null''')
rep('''    var p = { type: type, row: 0, col: SPAWN_COL[type], shape: SHAPES[type] };''',
    '''    var p = {
      type: type, row: 0, col: SPAWN_COL[type], rot: 0, shape: SHAPES[type],
      lockTicks: 0, lockResets: 0
    };''')
rep('''  // One gravity step. The real timer, tick() and soft drop all run this.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (fits(current, 1, 0)) {
      current.row += 1;
    } else {
      lock();
    }
  }

  function move(dCol) {
    if (status !== "running" || !current) return;
    if (fits(current, 0, dCol)) current.col += dCol;
  }
''','''  // One gravity step. The real timer, tick() and soft drop all run this.
  // If the piece cannot fall, the step counts one tick of lock delay instead.
  function gravityStep() {
    if (status !== "running" || !current) return;
    if (fits(current, 1, 0)) {
      current.row += 1;
      current.lockTicks = 0;
    } else {
      current.lockTicks += 1;
      if (current.lockTicks >= LOCK_DELAY) lock();
    }
  }

  // A sideways move while resting restarts the lock delay, up to
  // MAX_LOCK_RESETS times per piece.
  function move(dCol) {
    if (status !== "running" || !current) return;
    if (!fits(current, 0, dCol)) return;
    var resting = !fits(current, 1, 0);
    current.col += dCol;
    if (resting && current.lockResets < MAX_LOCK_RESETS) {
      current.lockResets += 1;
      current.lockTicks = 0;
    }
  }

  function rotatedShape(p) {
    var rot = (p.rot + 1) % 4;
    if (p.type === "I") return { rot: rot, shape: I_STATES[rot] };
    var size = p.type === "O" ? 2 : 3;
    return {
      rot: rot,
      shape: p.shape.map(function (off) { return [off[1], size - 1 - off[0]]; })
    };
  }

  // Rotate clockwise. If the turned shape does not fit, try shifting it
  // sideways; if nothing fits, leave the piece exactly as it was.
  function rotateCW() {
    if (status !== "running" || !current) return;
    var next = rotatedShape(current);
    var trial = { row: current.row, col: current.col, shape: next.shape };
    for (var i = 0; i < KICKS.length; i++) {
      if (fits(trial, 0, KICKS[i])) {
        current.col += KICKS[i];
        current.rot = next.rot;
        current.shape = next.shape;
        return;
      }
    }
  }
''')
rep('''    right: function () { move(1); },''','''    right: function () { move(1); },
    rotateCW: rotateCW,''')
rep('''    ArrowRight: "right",''','''    ArrowRight: "right",
    ArrowUp: "rotateCW",
    x: "rotateCW",
    X: "rotateCW",''')
open(p,'w').write(s)
