const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const pg = await b.newPage();
  const errs=[]; pg.on('pageerror', e=>errs.push(e.message));
  await pg.addInitScript(() => { window.setInterval = () => 0; });
  await pg.goto('file:///Users/vmysla/src/ab-study/arms/tetris-rep-control-03/control/index.html');
  const ev = (f, a) => pg.evaluate(f, a);
  let fail = 0; const ok = (n, c, x) => { if (!c) fail++; console.log((c?'PASS ':'FAIL ')+n+(c?'':' '+JSON.stringify(x))); };
  const T = () => window.__tetris;
  const st = () => ev(() => window.__tetris.getState());
  const run = (steps) => ev((steps) => { for (const [k,a] of steps) window.__tetris[k](a); return window.__tetris.getState(); }, steps);
  const E = Array(20).fill('..........');

  // T rotate at spawn
  let s = await run([['newGame',['T','I']],['input','rotateCW']]);
  ok('T rotates', JSON.stringify(s.current.cells.sort()) === JSON.stringify([[0,4],[1,4],[1,5],[2,4]].sort()), s.current.cells);
  s = await run([['input','rotateCW'],['input','rotateCW'],['input','rotateCW']]);
  ok('T 4 rotations = spawn', JSON.stringify(s.current.cells.sort()) === JSON.stringify([[0,4],[1,3],[1,4],[1,5]].sort()), s.current.cells);

  // I at spawn: vertical in-board
  s = await run([['newGame',['I','O']],['input','rotateCW']]);
  ok('I vertical', s.current.cells.every(([r,c])=>c===5 && r>=0), s.current.cells);
  // I vertical against right wall, rotate -> kick left
  s = await run([['input','right'],['input','right'],['input','right'],['input','right'],['input','right']]);
  ok('I at right wall', s.current.cells.every(([r,c])=>c===9), s.current.cells);
  s = await run([['input','rotateCW']]);
  ok('I kicked inside', s.current.cells.every(([r,c])=>c>=0&&c<10&&r>=0&&r<20) && new Set(s.current.cells.map(x=>x[0])).size===1, s.current.cells);

  // Refused rotation: I horizontal in a 4-wide well, 1 row deep, walls around
